import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, DirectionalLight, DoubleSide, RepeatWrapping } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hub-collection-row';

  // --- Row geometry -----------------------------------------------------
  const ROW_W = 6.4;
  const ROW_H = 0.9;

  const rowMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.18,
    side: DoubleSide,
  });

  const rowMesh = new THREE.Mesh(new PlaneGeometry(ROW_W, ROW_H), rowMat);
  rowMesh.name = 'row-plate';
  root.add(rowMesh);

  // load brushed metal texture from atlas region
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.wrapS = RepeatWrapping;
      tex.wrapT = RepeatWrapping;
      tex.repeat.set(1, 1);
      rowMat.map = tex;
      rowMat.needsUpdate = true;
    }).catch(() => {});
  }

  // --- Rim light (local, subtle accent) ---------------------------------
  const rim = new DirectionalLight(colors.accent, 0.7);
  rim.position.set(-2.5, 1.2, 2.0);
  root.add(rim);

  // --- Subtle divider (bottom edge) --------------------------------------
  const dividerMat = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.16,
  });
  const divider = new THREE.Mesh(new PlaneGeometry(ROW_W * 0.94, 0.012), dividerMat);
  divider.position.set(0, -ROW_H / 2 + 0.04, 0.01);
  root.add(divider);

  // --- Accent focus edge (hidden until focus/hover) -----------------------
  const edgeMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.0,
  });
  const edge = new THREE.Mesh(new PlaneGeometry(0.035, ROW_H * 0.78), edgeMat);
  edge.position.set(-ROW_W / 2 + 0.05, 0, 0.02);
  root.add(edge);

  // --- Text content (title / meta) — only if provided, never invented ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];

  const titleItem = items.find((i) => i.role === 'title' || i.role === 'headline');
  const metaItem = items.find((i) => i.role === 'meta' || i.role === 'caption' || i.role === 'body');

  if (titleItem?.text) {
    const title = ctx.fontAtlas.createText(titleItem.text, {
      fontSize: titleItem.typography?.fontSize ?? 34,
      color: colors.paper,
      align: 'left',
    });
    title.position.set(-ROW_W / 2 + 0.35, 0.08, 0.02);
    root.add(title);
    textNodes.push(title);
  }

  if (metaItem?.text) {
    const meta = ctx.fontAtlas.createText(metaItem.text, {
      fontSize: metaItem.typography?.fontSize ?? 20,
      color: colors.paper,
      align: 'right',
      letterSpacingPx: 1.2,
    });
    meta.position.set(ROW_W / 2 - 0.4, 0.02, 0.02);
    root.add(meta);
    textNodes.push(meta);
  }

  // --- Apply every declared cinematic primitive (none expected here) -----
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // --- Motion: hover lift / press-down / click emit -----------------------
  const timelines = [];
  const baseY = 0;
  let hovered = false;

  function killAllTweens() {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
  }

  function onPointerEnter() {
    if (hovered) return;
    hovered = true;
    killAllTweens();
    const tl = gsap.timeline();
    tl.to(root.position, { y: baseY + 0.15, duration: 0.5, ease: 'power3.out' }, 0);
    tl.to(rowMat, { roughness: 0.5, duration: 0.5, ease: 'power2.out' }, 0);
    tl.to(edgeMat, { opacity: 0.9, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function onPointerLeave() {
    hovered = false;
    killAllTweens();
    const tl = gsap.timeline();
    tl.to(root.position, { y: baseY, duration: 0.6, ease: 'power4.out' }, 0);
    tl.to(edgeMat, { opacity: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function onPointerDown() {
    const tl = gsap.timeline();
    tl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    timelines.push(tl);
  }

  function onPointerUp() {
    const tl = gsap.timeline();
    tl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power4.out' });
    timelines.push(tl);
  }

  function onClick() {
    ctx.emit('hub-collection.select', { rowId: config.id ?? 'hub-collection-row' });
  }

  root.userData.handlers = {
    pointerenter: onPointerEnter,
    pointerleave: onPointerLeave,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
    click: onClick,
    hover: onPointerEnter,
  };

  // --- Cleanup --------------------------------------------------------
  root.userData.cleanup = () => {
    killAllTweens();
    primitiveHandles.forEach((h) => {
      try { h.cleanup?.(); } catch (e) {}
    });

    rowMesh.geometry.dispose();
    rowMat.dispose();
    divider.geometry.dispose();
    dividerMat.dispose();
    edge.geometry.dispose();
    edgeMat.dispose();

    if (loadedTexture) {
      loadedTexture.dispose();
    }

    textNodes.forEach((n) => {
      n.traverse?.((c) => {
        c.geometry?.dispose?.();
        if (c.material) {
          if (Array.isArray(c.material)) c.material.forEach((m) => m.dispose());
          else c.material.dispose();
        }
      });
    });

    root.clear();
  };

  return root;
}
